const pickKey=()=>{const cs=(S.cos||[]).filter(c=>c.emp&&c.emp.key.length);if(!cs.length)return null;const c=pick(cs);return {c,k:pick(c.emp.key)}};
const keyT=f=>()=>{const x=S.tmpT=pickKey();return x?f(x.k,x.c):'社員のことで、相談があった。'};
const keyFx=(sk,mor,extra)=>()=>{const x=S.tmpT;if(x&&x.k){x.k.sk=clamp(x.k.sk+sk,1,99);coInit(x.c);x.c.emp.mor=clamp(x.c.emp.mor+mor)}return extra||{}};
const keyQuit=(extra)=>()=>{const x=S.tmpT;if(x&&x.c&&x.c.emp)x.c.emp.key=x.c.emp.key.filter(k=>k!==x.k);return extra||{}};
